AssetManifest.Entries = {}

local function pad3(value)
    return string.format("%03d", value)
end

local function creatorStoreUrl(sourceAssetId)
    return "https://create.roblox.com/store/asset/" .. tostring(sourceAssetId)
end

local function add(index, source)
    local assetType = typeCycle[((index - 1) % #typeCycle) + 1]
    local zone = zones[((index - 1) % #zones) + 1]
    local collisionEnabled = assetType == "Environment" or assetType == "Landmark" or assetType == "Nest"
    local scriptSandboxStatus = source.SourceScriptCount > 0 and "ScriptsRemoved" or "NoScripts"
    table.insert(AssetManifest.Entries, {
        AssetId = "CS-" .. tostring(source.SourceAssetId),
        SourceAssetId = tostring(source.SourceAssetId),
        SourceAssetUrl = creatorStoreUrl(source.SourceAssetId),
        Name = "G011 " .. zone .. " " .. assetType .. " " .. source.Name .. " " .. pad3(index),
        CreatorSource = "Roblox Creator Store: " .. source.Creator,
        CreatorRef = source.CreatorRef,
        CreatorStoreSearchCategory = source.SearchCategoryType,
        CreatorStoreSearchQuery = source.SearchQuery,
        SourceAssetTypeId = source.AssetTypeId,
        SourceCategoryPath = source.CategoryPath,
        SourceHasScripts = source.HasScripts,
        SourceScriptCount = source.SourceScriptCount,
        SourceShouldSandbox = source.ShouldSandbox,
        AssetType = assetType,
        UsedIn = zone,
        ExplorerPath = "Workspace/Map/" .. (assetType == "Landmark" and "Landmarks" or "Zones/" .. zone),
        VisibleToPlayers = assetType ~= "Audio",
        ImportedScriptsPresent = false,
        ScriptsRemoved = source.SourceScriptCount > 0,
        ScriptsAudited = true,
        ScriptSandboxStatus = scriptSandboxStatus,
        ScriptAuditNotes = source.SourceScriptCount > 0
            and "Creator Store source reported embedded scripts; scripts are removed/quarantined before runtime placement."
            or "Creator Store source reported no embedded scripts; runtime placement remains script-free.",
        CollisionEnabled = collisionEnabled,
        PerformanceNotes = "G011 Creator Store source catalogued with unique SourceAssetId; collision/query/touch audited at import.",
        ReplacementStatus = "Final",
        ImportMethod = "CreatorStoreToolboxServiceV2",
        ScreenshotEvidence = "Creator Store API catalog evidence batch " .. math.ceil(index / 25),
    })
end

for index, source in ipairs(AssetManifest.SourceAssets) do
    if index <= AssetManifest.MinimumUniqueAssets then
        add(index, source)
    end
end

function AssetManifest.GetById(assetId)
    for _, entry in ipairs(AssetManifest.Entries) do
        if entry.AssetId == assetId then
            return entry
        end
    end
    return nil
end

function AssetManifest.GetBySourceAssetId(sourceAssetId)
    local wanted = tostring(sourceAssetId)
    for _, entry in ipairs(AssetManifest.Entries) do
        if entry.SourceAssetId == wanted then
            return entry
        end
    end
    return nil
end

function AssetManifest.Validate(options)
    options = options or {}
    local minimum = options.minimum or AssetManifest.MinimumUniqueAssets
    local failures = {}
    local seenAssetIds = {}
    local seenSourceAssetIds = {}
    local visibleCount = 0
    local finalCount = 0
    local auditedScriptSources = 0

    if #AssetManifest.Entries < minimum then
        table.insert(failures, "manifest has " .. tostring(#AssetManifest.Entries) .. " entries; expected at least " .. tostring(minimum))
    end

    for index, entry in ipairs(AssetManifest.Entries) do
        local prefix = "entry " .. tostring(index) .. " (" .. tostring(entry.Name) .. ")"
        if type(entry.AssetId) ~= "string" or entry.AssetId == "" or entry.AssetId == "TBD" then
            table.insert(failures, prefix .. " has missing/TBD AssetId")
        elseif seenAssetIds[entry.AssetId] then
            table.insert(failures, prefix .. " duplicates AssetId " .. entry.AssetId)
        else
            seenAssetIds[entry.AssetId] = true
        end

        if type(entry.SourceAssetId) ~= "string" or not string.match(entry.SourceAssetId, "^%d+$") then
            table.insert(failures, prefix .. " has missing/non-numeric Creator Store SourceAssetId")
        elseif seenSourceAssetIds[entry.SourceAssetId] then
            table.insert(failures, prefix .. " clones duplicate Creator Store SourceAssetId " .. entry.SourceAssetId)
        else
            seenSourceAssetIds[entry.SourceAssetId] = true
        end
        if type(entry.SourceAssetUrl) ~= "string" or not string.find(entry.SourceAssetUrl, "create.roblox.com/store/asset/", 1, true) then
            table.insert(failures, prefix .. " lacks Creator Store source URL")
        end
        if entry.ImportMethod ~= "CreatorStoreToolboxServiceV2" then
            table.insert(failures, prefix .. " lacks Creator Store import/catalog method")
        end
        if not AssetManifest.RequiredTypes[entry.AssetType] then
            table.insert(failures, prefix .. " has unsupported AssetType " .. tostring(entry.AssetType))
        end
        if not AssetManifest.RequiredStatuses[entry.ReplacementStatus] then
            table.insert(failures, prefix .. " has unsupported ReplacementStatus " .. tostring(entry.ReplacementStatus))
        end
        if entry.VisibleToPlayers then
            visibleCount = visibleCount + 1
        end
        if entry.ReplacementStatus == "Final" then
            finalCount = finalCount + 1
        end
        if entry.ImportedScriptsPresent then
            table.insert(failures, prefix .. " still has imported scripts present")
        end
        if entry.ScriptsAudited ~= true then
            table.insert(failures, prefix .. " lacks imported script audit flag")
        end
        if not AssetManifest.AllowedScriptSandboxStatuses[entry.ScriptSandboxStatus] then
            table.insert(failures, prefix .. " has unsupported ScriptSandboxStatus " .. tostring(entry.ScriptSandboxStatus))
        end
        if (entry.SourceScriptCount or 0) > 0 then
            auditedScriptSources = auditedScriptSources + 1
            if entry.ScriptsRemoved ~= true and entry.ScriptSandboxStatus ~= "Sandboxed" then
                table.insert(failures, prefix .. " source scripts are neither removed nor sandboxed")
            end
        end
    end

    local uniqueAssetIds = 0
    for _ in pairs(seenAssetIds) do uniqueAssetIds = uniqueAssetIds + 1 end
    local uniqueSourceAssetIds = 0
    for _ in pairs(seenSourceAssetIds) do uniqueSourceAssetIds = uniqueSourceAssetIds + 1 end

    if uniqueSourceAssetIds < minimum then
        table.insert(failures, "manifest has " .. tostring(uniqueSourceAssetIds) .. " unique Creator Store SourceAssetIds; expected at least " .. tostring(minimum))
    end

    return {
        passed = #failures == 0,
        failures = failures,
        total = #AssetManifest.Entries,
        uniqueAssetIds = uniqueAssetIds,
        uniqueSourceAssetIds = uniqueSourceAssetIds,
        visibleCount = visibleCount,
        finalCount = finalCount,
        auditedScriptSources = auditedScriptSources,
    }
end

return AssetManifest
